-- Approved availability opening and caller-introduction answers.
WITH revised AS (SELECT id,replace(content::text,'Hi, is {first_name} speaking?','Hi, is {first_name} available?')::jsonb AS c FROM daisy_call_scripts WHERE deleted_at IS NULL AND ((script_number=40 AND version=31) OR (script_number IN (60,61) AND version=2)))
UPDATE daisy_call_scripts s SET history=coalesce(history,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('version',version,'title',title,'category',category,'direction',direction,'content',content,'saved_at',now())),content=r.c||jsonb_build_object('identity_handling','Start with Hi, is {first_name} available? If asked Who’s speaking, May I ask who is speaking, Who is this or Who is calling, answer This is Daisy with the Down Payment Assistance Help Center, then ask whether the customer is available. Do not disclose their form or financial details before identity is confirmed. If someone offers to get the customer, say Thank you, I’ll hold and wait. A bare yes to availability calls for Am I speaking with {first_name}?; a matching-name response confirms identity. If unavailable, leave the approved neutral message and end.','key_points',(SELECT coalesce(jsonb_agg(point),'[]'::jsonb) FROM jsonb_array_elements_text(r.c->'key_points') point WHERE point NOT LIKE 'Start with:%')||jsonb_build_array('Start with Hi, is {first_name} available? If asked Who’s speaking, May I ask who is speaking, Who is this or Who is calling, answer This is Daisy with the Down Payment Assistance Help Center, then ask whether the customer is available. Do not disclose their form or financial details before identity is confirmed. If someone offers to get the customer, say Thank you, I’ll hold and wait. A bare yes to availability calls for Am I speaking with {first_name}?; a matching-name response confirms identity. If unavailable, leave the approved neutral message and end.')),version=version+1,updated_at=now() FROM revised r WHERE s.id=r.id;
